// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /notes/create').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Not ekleme isteğini doğrular ve not belgesini hazırlar.
const crypto = require('crypto');
const b = $('POST /notes/create').first().json.body || {};
const user_id = $('Not ekle: oturum').first().json.user_id;
const s = (v) => (v === null || v === undefined ? '' : String(v).trim());
const course_id = s(b.course_id);
const title = s(b.title).replace(/\s+/g, ' ');
const content = s(b.content).replace(/\r\n/g, '\n');
const source = s(b.source) || 'text';
const fail = (message) => [{ json: { valid: false, response: { ok: false, error: { code: 'VALIDATION_ERROR', message } } } }];

if (!course_id) return fail('Ders seçilmelidir.');
if (!title || title.length > 200) return fail('Not başlığı 1-200 karakter arasında olmalıdır.');
if (content.length < 20 || content.length > 15000) return fail('Not metni 20-15000 karakter arasında olmalıdır.');
if (!['text', 'txt', 'pdf'].includes(source)) return fail("Kaynak 'text', 'txt' veya 'pdf' olmalıdır.");

const note = { id: crypto.randomUUID(), user_id, course_id, title, content, source, created_at: new Date().toISOString() };
return [{ json: { valid: true, note, response: { ok: true, data: { note: { id: note.id, title, created_at: note.created_at } } } } }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /notes/list').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Dersin notlarını önizleme ve özet durumu ile döndürür (en yeni önce).
const iso = (v) => (v ? new Date(v).toISOString() : null);
const notes = $input.all().map((i) => i.json).filter((d) => d && d.id)
  .map((n) => ({
    id: n.id,
    title: n.title,
    preview: String(n.content || '').replace(/\s+/g, ' ').slice(0, 160),
    has_summary: !!(n.summary && n.summary.short),
    source: n.source || 'text',
    created_at: iso(n.created_at),
  }))
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
return [{ json: { response: { ok: true, data: { notes } } } }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /notes/summarize').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Özet isteğini okur.
const b = $('POST /notes/summarize').first().json.body || {};
const s = (v) => (v === null || v === undefined ? '' : String(v).trim());
return [{
  json: {
    user_id: $('Özet: oturum').first().json.user_id,
    note_id: s(b.note_id) || '-',
    force: b.force === true || b.force === 'true',
    model: s(b.model) || null,
  },
}];

// Özet için Ollama isteğini hazırlar. "format" ile JSON şeması zorlanır.
const n = $('Özet: not').first().json;
const r = $('Özet: istek').first().json;
const schema = {
  type: 'object',
  properties: {
    short: { type: 'string' },
    key_points: { type: 'array', items: { type: 'string' }, minItems: 3, maxItems: 7 },
    keywords: { type: 'array', items: { type: 'string' }, minItems: 3, maxItems: 8 },
    flashcards: {
      type: 'array', minItems: 4, maxItems: 8,
      items: {
        type: 'object',
        properties: { front: { type: 'string' }, back: { type: 'string' } },
        required: ['front', 'back'],
      },
    },
  },
  required: ['short', 'key_points', 'keywords', 'flashcards'],
};
const system = [
  'Sen üniversite öğrencileri için ders notlarını özetleyen bir asistansın.',
  'KURALLAR:',
  '1. YALNIZCA Türkçe yaz. Çince, Japonca, Korece veya Kiril alfabesinden tek bir karakter bile kullanma.',
  '2. Yalnızca nottaki bilgileri kullan; notta olmayan bilgi ekleme.',
  '3. "short": notun 2-3 cümlelik özeti.',
  '4. "key_points": notun en önemli 3-7 maddesi; her madde kısa tek bir cümle.',
  '5. "keywords": notun 3-8 anahtar kavramı (tek kelime veya kısa ifade).',
  '6. "flashcards": sınav öncesi hızlı tekrar için 4-8 hap bilgi kartı. "front" kısa bir kavram veya soru '
    + '(en fazla 8 kelime), "back" ezberlenecek bilgi (tek cümle; formül varsa formülü yaz).',
  '7. Yanıtın yalnızca istenen JSON nesnesi olsun.',
].join('\n');
return [{
  json: {
    route: 'text',
    body: {
      model: r.model, // null ise .env içindeki LLM_MODEL
      stream: false,
      format: schema,
      options: { temperature: 0.2, num_ctx: 8192 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `Ders notu başlığı: ${n.title}\n\nDers notu:\n${n.content}` },
      ],
    },
  },
}];

// Özeti nota kaydetmek için güncelleme belgesini ve istemci yanıtını hazırlar.
const n = $('Özet: not').first().json;
const v = $input.first().json;
const now = new Date().toISOString();
return [{
  json: {
    id: n.id,
    summary: v.summary,
    summary_model: v.model,
    summarized_at: now,
    response: { ok: true, data: { note_id: n.id, summary: v.summary, model: v.model, cached: false } },
  },
}];

// Model özetini doğrular. Kurallardan biri bozulursa yeniden denenir ($runIndex: deneme sırası).
const r = $input.first().json;
const raw = (r.message && typeof r.message.content === 'string') ? r.message.content : '';
const FOREIGN = /[぀-ヿ㐀-䶿一-鿿豈-﫿가-힯Ѐ-ӿ]/;
const clean = (v) => String(v ?? '').trim();
const list = (a, max) => (Array.isArray(a) ? [...new Set(a.map(clean).filter(Boolean))].slice(0, max) : []);

let problem = null;
let summary = null;
try {
  const j = JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
  // Hap bilgi kartları: boş veya aşırı uzun kartlar atılır, en fazla 8 kart
  const cards = Array.isArray(j.flashcards)
    ? j.flashcards.map((c) => ({ front: clean(c && c.front), back: clean(c && c.back) }))
        .filter((c) => c.front && c.back && c.front.length <= 120 && c.back.length <= 300).slice(0, 8)
    : [];
  summary = { short: clean(j.short), key_points: list(j.key_points, 7), keywords: list(j.keywords, 8), flashcards: cards };
  if (!summary.short) problem = 'özet boş';
  else if (summary.key_points.length < 3) problem = 'en az 3 ana madde gerekli';
  else if (summary.keywords.length < 3) problem = 'en az 3 anahtar kavram gerekli';
  else if (summary.flashcards.length < 4) problem = 'en az 4 hap bilgi kartı gerekli';
  else if (FOREIGN.test(JSON.stringify(summary))) problem = 'Türkçe dışı karakter';
} catch (e) {
  problem = 'geçersiz JSON';
}
return [{ json: { valid: problem === null, problem, attempt: $runIndex + 1, summary, model: r.model || null } }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /notes/extract-pdf').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Yüklenen dosyayı bulur ve "pdf" adlı ikili alana taşır (n8n çok parçalı formda alan adını
// sürüme göre farklı adlandırabildiği için ilk dosya alınır).
const req = $('POST /notes/extract-pdf').first();
const files = req.binary || {};
const key = Object.keys(files)[0];
const fail = (message) => [{ json: { valid: false, response: { ok: false, error: { code: 'VALIDATION_ERROR', message } } } }];
if (!key) return fail('PDF dosyası gönderilmedi.');
const file = files[key];
const name = String(file.fileName || '');
const isPdf = /\.pdf$/i.test(name) || String(file.mimeType || '').includes('pdf');
if (!isPdf) return fail('Yalnızca PDF dosyası yüklenebilir.');
return [{ json: { valid: true, file_name: name }, binary: { pdf: file } }];

// PDF'ten çıkan metni temizler: satır sonu tireleri, fazla boşluk ve boş satırlar.
const r = $input.first().json;
const name = $('PDF: dosya').first().json.file_name;
let text = String(r.text || '')
  .replace(/\r\n?/g, '\n')
  .replace(/(\p{L})-\n(\p{L})/gu, '$1$2')   // satır sonunda bölünmüş kelimeler: "geliş-\ntirilen"
  .replace(/[ \t]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/([^.!?:;\n])\n(?!\n)/g, '$1 ')  // paragraf içindeki satır kırılımları: PDF satırları birleşir
  .trim();
if (text.length < 20) {
  return [{ json: { valid: false, response: { ok: false, error: { code: 'PDF_NO_TEXT',
    message: 'PDF\'te seçilebilir metin bulunamadı. Taranmış (resim) bir belge olabilir; metni elle yapıştırmayı deneyin.' } } } }];
}
return [{
  json: {
    valid: true,
    response: {
      ok: true,
      data: {
        text,
        characters: text.length,
        pages: Number(r.numpages || r.numPages || 0) || null,
        file_name: name,
        title: name.replace(/\.pdf$/i, ''),
      },
    },
  },
}];
